def trial(name, port, slices, lv=1, img=IMG):
    subprocess.run(["docker", "rm", "-f", name], capture_output=True)
    subprocess.run(["docker", "run", "--rm", "-d", "--name", name, "--gpus", "all", "-v", SC + ":/work", "-v", OUT + ":/out",
